Higher order component is a special component it take input as a existing component return as a new component.
Mailny using the Reusable purpose. This is classbase component
import React from 'react';
const withLogger = (WrappedComponent) => {
class WithLogger extends React.Component {
componentDidMount() {
console.log('Component mounted');
}
componentWillUnmount() {
console.log('Component unmounted');
}
render() {
return <WrappedComponent {...this.props} />;
}
}
return WithLogger;
};
// Usage
class MyComponent extends React.Component {
render() {
return <div>Hello, World!</div>;
}
}
const MyComponentWithLogger = withLogger(MyComponent);
export default MyComponentWithLogger;

